#!/usr/bin/env python3
"""
Script to reproduce the bug with mocked classmethod.
"""

import pytest
from oop_ext.interface import Interface, ImplementsInterface, AssertImplements


def test_requires_declaration_bug():
    """Test that reproduces the issue with mocked classmethod."""

    class IFoo(Interface):
        @classmethod
        def foo(cls):
            ""

    @ImplementsInterface(IFoo)
    class FooImplementation:
        @classmethod
        def foo(cls):
            ""

    # This should work - let's test it first
    print("Testing without mock...")
    AssertImplements(FooImplementation, IFoo, requires_declaration=True)
    print("✓ Works without mock")

    # Now let's try to reproduce the issue with mock
    # We'll need pytest-mock for this
    import unittest.mock

    print("Testing with mock...")
    # Mock the classmethod
    with unittest.mock.patch.object(FooImplementation, "foo") as mock_foo:
        # The mock should be a MagicMock
        print(f"Mock type: {type(mock_foo)}")
        print(f"foo attribute type: {type(FooImplementation.foo)}")

        # This should fail according to the bug report
        try:
            AssertImplements(FooImplementation, IFoo, requires_declaration=True)
            print("✓ Works with mock - bug is fixed!")
        except AssertionError as e:
            print(f"✗ Failed with mock - bug reproduced: {e}")
            raise


def test_spy_approach():
    """Test using spy approach similar to the bug report."""

    class IFoo(Interface):
        @classmethod
        def foo(cls):
            ""

    @ImplementsInterface(IFoo)
    class FooImplementation:
        @classmethod
        def foo(cls):
            ""

    # This should work - let's test it first
    print("Testing without spy...")
    AssertImplements(FooImplementation, IFoo, requires_declaration=True)
    print("✓ Works without spy")

    # Now let's try to reproduce using spy approach  
    print("Testing with spy...")
    import unittest.mock

    # Create a spy
    original_foo = FooImplementation.foo
    spy = unittest.mock.spy = unittest.mock.MagicMock(wraps=original_foo)
    FooImplementation.foo = spy

    try:
        print(f"foo attribute type: {type(FooImplementation.foo)}")
        AssertImplements(FooImplementation, IFoo, requires_declaration=True)
        print("✓ Works with spy - bug is fixed!")
    except AssertionError as e:
        print(f"✗ Failed with spy - bug reproduced: {e}")
        # Restore original
        FooImplementation.foo = original_foo
        raise

    # Restore original
    FooImplementation.foo = original_foo


if __name__ == "__main__":
    print("=== Testing Requires Declaration Bug ===")

    try:
        test_requires_declaration_bug()
    except Exception as e:
        print(f"First test failed as expected: {e}")

    print("\n=== Testing Spy Approach ===")
    try:
        test_spy_approach()
    except Exception as e:
        print(f"Second test failed as expected: {e}")

